// Graph using adjacency list
class Graph {
public:
    int vertices;
    vector<vector<int>> adjList;

    Graph(int v) : vertices(v), adjList(v) {}

    void addEdge(int u, int v) {
        adjList[u].push_back(v);
        adjList[v].push_back(u); // omit this line for directed graph
    }
};

void bfs(Graph& g, int start) {
    vector<bool> visited(g.vertices, false);
    queue<int> q;
    q.push(start);
    visited[start] = true;

    while (!q.empty()) {
        int node = q.front(); q.pop();
        cout << node << " ";
        for (int neighbor : g.adjList[node]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                q.push(neighbor);
            }
        }
    }
}

// Graph using adjacency list (Map of arrays)
class Graph {
  constructor() {
    this.adjList = new Map();
  }

  addEdge(u, v) {
    if (!this.adjList.has(u)) this.adjList.set(u, []);
    if (!this.adjList.has(v)) this.adjList.set(v, []);
    this.adjList.get(u).push(v);
    this.adjList.get(v).push(u); // omit for directed graph
  }

  bfs(start) {
    const visited = new Set([start]);
    const queue = [start];
    const order = [];

    while (queue.length) {
      const node = queue.shift();
      order.push(node);
      for (const neighbor of this.adjList.get(node) || []) {
        if (!visited.has(neighbor)) {
          visited.add(neighbor);
          queue.push(neighbor);
        }
      }
    }
    return order;
  }
}

