items.correct:
bool hasCycle(int node, vector<bool>& visited, vector<bool>& inStack) {
    visited[node] = true;
    inStack[node] = true;
    for (int n : adjList[node]) {
        if (!visited[n] && hasCycle(n, visited, inStack)) return true;
        else if (inStack[n]) return true; // back edge = real cycle
    }
    inStack[node] = false;
    return false;
}
